public class WindowMaxScanner {

    public static int[] windowMaxima(int[] values, int window) {
        if (window < 1 || window > values.length) {
            return new int[0];
        }
        int[] maxima = new int[values.length - window + 1];
        for (int start = 0; start < maxima.length; start++) {
            int best = values[start];
            for (int i = start + 1; i < start + window; i++) {
                if (values[i] > best) {
                    best = values[i];
                }
            }
            maxima[start] = best;
        }
        return maxima;
    }
}
